package com.lolfm.simulator;
public final class PlayerProgressionPowerEvaluator {public ProgressionPowerBreakdown evaluate(PlayerState p,ProgressionCombatContext c,boolean on){return evaluate(p.getProgressionState(),c,on);}public ProgressionPowerBreakdown evaluate(PlayerProgressionState s,ProgressionCombatContext c,boolean on){double lp=on&&s.isEnabled()?Math.max(0,s.getLevel()-1)*ProgressionRuleConfig.LEVEL_POWER_PER_LEVEL_ABOVE_ONE:0,ip=on&&s.isEnabled()?ProgressionRuleConfig.itemPower(s.getItemStage()):0,cm=1,sp=0,raw=(lp+ip)*cm+sp,total=Math.max(0,Math.min(ProgressionRuleConfig.MAX_PLAYER_PROGRESSION_POWER,raw));return new ProgressionPowerBreakdown(s.getLevel(),s.getItemStage(),lp,ip,cm,sp,raw,total,c);}}
